schema:
CREATE TABLE Bar (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('B1', 'Addr1');
INSERT INTO Bar (name, address) VALUES ('B2', 'Addr2');

INSERT INTO Beer (name, brewer) VALUES ('X', 'BrewA');
INSERT INTO Beer (name, brewer) VALUES ('Y', 'BrewB');

INSERT INTO Drinker (name, address) VALUES ('Alice', 'DAddr1');
INSERT INTO Drinker (name, address) VALUES ('Bob', 'DAddr2');

INSERT INTO Serves (bar, beer, price) VALUES ('B1', 'X', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('B2', 'Y', 6.00);

INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'B1', 3);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'B2', 4);

INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'X');

