INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'B1', 3);
INSERT INTO Serves (bar, beer, price) VALUES ('B1', 'X', 5.00), ('B1', 'Y', 6.00);
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'X'), ('Alice', 'Y');

